import UIKit

// Simple program to find and interact with dialogs
print("Attempting to find and dismiss dialogs...")

// Try to find the main window
if let windowScene = UIApplication.shared.connectedScenes.first as? UIWindowScene,
   let window = windowScene.windows.first {
    print("Found main window")

    // Look for alert controllers
    var current: UIViewController? = window.rootViewController
    while let vc = current {
        print("Checking view controller: \(type(of: vc))")

        if let alert = vc as? UIAlertController {
            print("Found alert controller!")
            // Try to find and tap the Open button
            for action in alert.actions {
                print("Found action: \(action.title ?? "unknown")")
                if action.title == "Open" {
                    action.handler?(action)
                    print("Triggered Open action!")
                }
            }
        }

        current = vc.presentedViewController
    }
}

print("Done")
